        VersionEntry(
            version: "版本 2.0.39 (Build 773)",
            date: "2026-07-18",
            changes: [
                "修复 Build 772 的真实回归:长录音下让候选(真实核心)直接权威、跳过完整 final ASR,导致准确率明显下降,出现否定词识别反义(“不要”识别成“我要”)等语义级错误。",
                "根因:候选识别器每次只看 8 秒滑动窗口拼接,完整 final ASR 有整段音频的完整上下文;短录音下两者质量接近,长连续语音下窗口拼接明显更容易出错。",
                "现在按录音时长分派:录音时长不超过 20 秒时继续信任候选直接交付(省等待时间);超过 20 秒无条件走完整 final ASR,不再比较候选来源或长度。20 秒门槛基于两个真实数据点(约 11 秒候选质量良好、约 100 秒候选质量明显下降)保守选定,后续可用更多真实录音校准。",
                "同时修复候选文本仍被传给下游 FinalRecognitionUseCase 的遗漏——该组件自身也有一道候选长度判断,超时长时必须连候选文本一起屏蔽,否则下游会自行放行候选、绕开完整识别。",
                "FinalDeliveryUseCaseCheck 新增长录音强制走完整 final ASR 的测试用例。"
